    {"id": 1227, "level": "helper", "korean": "오후 6시에 문을 닫아요.", "english": "It closes at 6 p.m.", "hint": "close at + 시각"},
    {"id": 1228, "level": "helper", "korean": "여기서는 사진 촬영이 금지예요.", "english": "Photography isn't allowed here.", "hint": "isn't allowed = 허용되지 않는다"},
    {"id": 1229, "level": "helper", "korean": "이 앱을 쓰시면 훨씬 편해요.", "english": "This app will make it much easier for you.", "hint": "make it easier = 더 쉽게 만들다"},
    {"id": 1230, "level": "helper", "korean": "교통카드를 사시는 게 좋아요.", "english": "You should buy a transportation card.", "hint": "transportation card = 교통카드"},
    {"id": 1231, "level": "helper", "korean": "편의점에서 충전할 수 있어요.", "english": "You can recharge it at a convenience store.", "hint": "recharge = 충전하다"},
    {"id": 1232, "level": "helper", "korean": "제 번호를 드릴게요. 도움이 필요하면 연락하세요.", "english": "Let me give you my number. Contact me if you need help.", "hint": "Contact me if ~ = ~하면 연락하세요"},
    {"id": 1233, "level": "helper", "korean": "한국에 오신 걸 환영합니다!", "english": "Welcome to Korea!", "hint": "Welcome to + 장소"},
    {"id": 1234, "level": "helper", "korean": "한국 여행은 어떠세요?", "english": "How do you like Korea so far?", "hint": "so far = 지금까지"},
    {"id": 1235, "level": "helper", "korean": "조금만 천천히 말씀해 주시겠어요?", "english": "Could you speak a little slower?", "hint": "speak slower = 더 천천히 말하다"},
    {"id": 1236, "level": "helper", "korean": "제 영어가 서툴러서 죄송해요.", "english": "Sorry, my English isn't very good.", "hint": "isn't very good = 그리 좋지 않다"},
    {"id": 1237, "level": "helper", "korean": "제가 제대로 이해했는지 확인할게요.", "english": "Let me make sure I understood correctly.", "hint": "make sure = 확실히 하다"},
    {"id": 1238, "level": "helper", "korean": "다른 도움이 필요하시면 말씀하세요.", "english": "Let me know if you need anything else.", "hint": "Let me know if ~ / anything else = 다른 것"},
    {"id": 1239, "level": "helper", "korean": "즐거운 여행 되세요!", "english": "Enjoy your trip!", "hint": "Enjoy your + 명사"},
